//! The social services' content tables, compiled in from `data/social/*.tsv`.
//!
//! Generated by `tools/ps4_setup/d1-social-tables.py` from Bungie's final D1 manifest (a local
//! input, never committed) joined to the client's own tables (vendor rows, item content indices,
//! the unlock-flag table). Each file's header names its sources. They hold derived facts only:
//! a few numbers per vendor, sale, category, item, bounty, engram and activity.

use std::collections::{BTreeMap, HashMap};
use std::sync::OnceLock;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VendorRow {
    pub index: u8,
    pub hash: u32,
    pub reset_interval: i64,
    pub reset_offset: i64,
    pub faction: u32,
    pub progression: u32,
    pub sales: u16,
    pub refundable: u16,
    pub event: u32,
    pub inhibit_buying: bool,
    pub name: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SaleRule {
    pub category: u16,
    /// DestinyVendorItemRefundPolicy: 0 NotRefundable, 1 DeletesItem, 2 RevokesLicense.
    pub refund_policy: u8,
    /// Minutes.
    pub refund_limit: u32,
    pub required_level: u32,
    pub failure_mask: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Category {
    /// How many of the category's sales one refresh offers (0 = no limit).
    pub quantity: u32,
    pub hide: bool,
    pub title: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ItemAction {
    None,
    Shard,
    Decrypt,
    Open,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ItemRow {
    pub bucket: u8,
    /// Manifest tierType: 2 Basic, 3 Common, 4 Rare, 5 Legendary, 6 Exotic.
    pub tier: u8,
    /// 0 Titan, 1 Hunter, 2 Warlock, 3 any.
    pub class: u8,
    pub flags: u8,
    pub max_stack: u32,
    pub item_type: u8,
    pub action: ItemAction,
    pub reward_set: i32,
}

pub const FLAG_NON_TRANSFERRABLE: u8 = 1;
pub const FLAG_EQUIPPABLE: u8 = 2;
pub const FLAG_INSTANCED: u8 = 4;
pub const FLAG_EXCLUSIVE: u8 = 8;

pub const TIER_LEGENDARY: u8 = 5;
pub const TIER_EXOTIC: u8 = 6;

impl ItemRow {
    pub fn instanced(&self) -> bool {
        self.flags & FLAG_INSTANCED != 0
    }
    pub fn transferrable(&self) -> bool {
        self.flags & FLAG_NON_TRANSFERRABLE == 0
    }
    pub fn equippable(&self) -> bool {
        self.flags & FLAG_EQUIPPABLE != 0
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BountyRow {
    /// 4 bounty, 12 quest step.
    pub item_type: u8,
    /// (objective hash, completion value).
    pub objectives: Vec<(u32, u32)>,
    /// (reward item content index, amount); the reward items are pseudo-items (Experience,
    /// reputation) or real items.
    pub rewards: Vec<(u16, u32)>,
    pub next: Option<u16>,
    pub questline: Option<u16>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EngramRow {
    pub vendor: u8,
    pub sale: u16,
    pub engram: u16,
    pub tier: u8,
    /// The client bucket ordinal it decodes into (None when the manifest bucket has no ordinal).
    pub bucket: Option<u8>,
    pub class: u8,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ActivityRow {
    pub index: u16,
    pub hash: u32,
    pub level: u32,
    pub tier: u32,
    pub type_hash: u32,
    pub destination: u32,
    /// The completion flag's master row, kind and sub (kind 3 = the profile completion record).
    pub completion: Option<(u16, u8, u16)>,
    pub matchmade: bool,
    pub playlist: bool,
    pub type_name: String,
    pub name: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Progression {
    pub name: String,
    pub repeat_last: bool,
    pub steps: Vec<u32>,
}

#[derive(Debug, Default)]
pub struct Tables {
    pub vendors: BTreeMap<u8, VendorRow>,
    pub rules: HashMap<(u8, u16), SaleRule>,
    pub categories: HashMap<(u8, u16), Category>,
    pub items: HashMap<u16, ItemRow>,
    pub bounties: HashMap<u16, BountyRow>,
    /// Reward pseudo-item content -> (its hash, its name).
    pub reward_items: HashMap<u16, (u32, String)>,
    pub progressions: HashMap<u32, Progression>,
    /// By engram content index.
    pub engrams: HashMap<u16, EngramRow>,
    pub decode_sales: HashMap<(u8, u16), u16>,
    pub activities: BTreeMap<u16, ActivityRow>,
    /// reward set -> (items using it, client tier byte, bucket).
    pub dismantle_sets: HashMap<i32, (u32, u8, u8)>,
}

fn rows(text: &str) -> impl Iterator<Item = Vec<&str>> {
    text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()).skip(1).map(|l| l.split('\t').collect())
}

fn n<T: std::str::FromStr + Default>(s: &str) -> T {
    s.parse().unwrap_or_default()
}

fn hex32(s: &str) -> u32 {
    u32::from_str_radix(s.trim_start_matches("0x"), 16).unwrap_or(0)
}

fn pairs(s: &str) -> Vec<(i64, i64)> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').filter_map(|p| {
        let (a, b) = p.split_once(':')?;
        Some((a.parse().ok()?, b.parse().ok()?))
    }).collect()
}

impl Tables {
    pub fn parse() -> Tables {
        let mut t = Tables::default();
        for r in rows(include_str!("../data/social/vendors.tsv")) {
            if r.len() < 11 {
                continue;
            }
            let v = VendorRow {
                index: n(r[0]), hash: hex32(r[1]), reset_interval: n(r[2]), reset_offset: n(r[3]), faction: n(r[4]),
                progression: n(r[5]), sales: n(r[6]), refundable: n(r[7]), event: n(r[8]), inhibit_buying: r[9] == "1",
                name: r[10].to_string(),
            };
            t.vendors.insert(v.index, v);
        }
        for r in rows(include_str!("../data/social/vendor-sale-rules.tsv")) {
            if r.len() < 7 {
                continue;
            }
            t.rules.insert((n(r[0]), n(r[1])), SaleRule {
                category: n(r[2]), refund_policy: n(r[3]), refund_limit: n(r[4]), required_level: n(r[5]), failure_mask: n(r[6]),
            });
        }
        for r in rows(include_str!("../data/social/vendor-categories.tsv")) {
            if r.len() < 5 {
                continue;
            }
            t.categories.insert((n(r[0]), n(r[1])), Category {
                quantity: n(r[2]), hide: r[3] == "1", title: r.get(5).copied().unwrap_or("").to_string(),
            });
        }
        for r in rows(include_str!("../data/social/items.tsv")) {
            if r.len() < 9 {
                continue;
            }
            let action = match r[7] { "shard" => ItemAction::Shard, "decrypt" => ItemAction::Decrypt, "open" => ItemAction::Open, _ => ItemAction::None };
            t.items.insert(n(r[0]), ItemRow {
                bucket: n(r[1]), tier: n(r[2]), class: n(r[3]), flags: n(r[4]), max_stack: n(r[5]), item_type: n(r[6]),
                action, reward_set: r[8].parse().unwrap_or(-1),
            });
        }
        for r in rows(include_str!("../data/social/bounties.tsv")) {
            if r.len() < 6 {
                continue;
            }
            let opt = |s: &str| s.parse::<i32>().ok().filter(|v| *v >= 0).map(|v| v as u16);
            t.bounties.insert(n(r[0]), BountyRow {
                item_type: n(r[1]),
                objectives: pairs(r[2]).into_iter().map(|(a, b)| (a as u32, b as u32)).collect(),
                rewards: pairs(r[3]).into_iter().filter(|(a, _)| *a >= 0).map(|(a, b)| (a as u16, b as u32)).collect(),
                next: opt(r[4]),
                questline: opt(r[5]),
            });
        }
        for r in rows(include_str!("../data/social/reward-items.tsv")) {
            if r.len() >= 3 {
                t.reward_items.insert(n(r[0]), (n(r[1]), r[2].to_string()));
            }
        }
        for r in rows(include_str!("../data/social/progressions.tsv")) {
            if r.len() >= 5 {
                t.progressions.insert(n(r[0]), Progression {
                    name: r[1].to_string(), repeat_last: r[3] == "1", steps: r[4].split(',').map(n).collect(),
                });
            }
        }
        for r in rows(include_str!("../data/social/engrams.tsv")) {
            if r.len() < 6 {
                continue;
            }
            let b: i32 = r[4].parse().unwrap_or(-1);
            let e = EngramRow { vendor: n(r[0]), sale: n(r[1]), engram: n(r[2]), tier: n(r[3]),
                                bucket: (b >= 0).then_some(b as u8), class: n(r[5]) };
            t.decode_sales.insert((e.vendor, e.sale), e.engram);
            t.engrams.entry(e.engram).or_insert(e);
        }
        for r in rows(include_str!("../data/social/activities.tsv")) {
            if r.len() < 13 {
                continue;
            }
            let row: i32 = r[6].parse().unwrap_or(-1);
            let a = ActivityRow {
                index: n(r[0]), hash: hex32(r[1]), level: n(r[2]), tier: n(r[3]), type_hash: n(r[4]), destination: n(r[5]),
                completion: (row >= 0).then(|| (row as u16, n(r[7]), n(r[8]))),
                matchmade: r[9] == "1", playlist: r[10] == "1", type_name: r[11].to_string(), name: r[12].to_string(),
            };
            t.activities.insert(a.index, a);
        }
        for r in rows(include_str!("../data/social/dismantle-sets.tsv")) {
            if r.len() >= 4 {
                t.dismantle_sets.insert(r[0].parse().unwrap_or(-1), (n(r[1]), n(r[2]), n(r[3])));
            }
        }
        t
    }

    pub fn vendor_by_hash(&self, hash: u32) -> Option<&VendorRow> {
        self.vendors.values().find(|v| v.hash == hash)
    }

    pub fn vendor_named(&self, name: &str) -> impl Iterator<Item = &VendorRow> {
        let name = name.to_string();
        self.vendors.values().filter(move |v| v.name == name)
    }

    /// The sales of a vendor in one category.
    pub fn category_sales(&self, vendor: u8, category: u16) -> Vec<u16> {
        let Some(v) = self.vendors.get(&vendor) else { return Vec::new() };
        (0..v.sales).filter(|s| self.rules.get(&(vendor, *s)).map(|r| r.category) == Some(category)).collect()
    }

    pub fn category_title(&self, vendor: u8, sale: u16) -> &str {
        self.rules.get(&(vendor, sale)).and_then(|r| self.categories.get(&(vendor, r.category))).map(|c| c.title.as_str()).unwrap_or("")
    }
}

pub fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(Tables::parse)
}

/// The sale table of the 56578 client (`ps4/fixtures/56578/vendor/vendor-sales.tsv`), for tests.
#[cfg(test)]
pub fn fixture_sales() -> &'static HashMap<(u8, u16), crate::vendor::Sale> {
    static S: OnceLock<HashMap<(u8, u16), crate::vendor::Sale>> = OnceLock::new();
    S.get_or_init(|| crate::vendor::parse_sales(include_str!("../../../../fixtures/56578/vendor/vendor-sales.tsv")))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_parse_with_their_controls() {
        let t = tables();
        assert_eq!(t.vendors[&6].name, "Guardian Outfitter");
        assert_eq!(t.vendors[&6].hash, 0x080760B4);
        assert_eq!(t.vendors[&5].name, "Agent of the Nine");
        assert_eq!((t.vendors[&5].reset_interval, t.vendors[&5].reset_offset), (10080, -12060));
        assert_eq!(t.vendors[&12].name, "Eververse");
        assert_eq!(t.vendors[&12].refundable, 67);
        // Only Tess's two stores have refundable sales in the final manifest.
        let refundable: Vec<&str> = t.vendors.values().filter(|v| v.refundable > 0).map(|v| v.name.as_str()).collect();
        assert_eq!(refundable, vec!["Eververse", "Silver Dust Vendor"]);
        assert_eq!(t.rules[&(12, 60)].refund_policy, 2, "Air Guitar revokes its licence on refund");
        assert_eq!(t.rules[&(12, 60)].refund_limit, 15);
        assert_eq!(t.items[&3598].bucket, 2, "the Khvostov is a primary weapon");
        assert_eq!(t.activities[&166].completion, Some((132, 3, 42)), "Restoration completes sub 42");
        assert_eq!(t.activities[&164].completion, Some((130, 3, 40)), "A Guardian Rises completes sub 40");
        assert_eq!(t.activities[&0].name, "Tower");
        assert!(t.bounties.values().any(|b| b.item_type == 4 && !b.objectives.is_empty()));
        assert!(!t.engrams.is_empty());
        assert_eq!(t.reward_items.values().find(|r| r.1 == "Experience").map(|r| r.0), Some(3006793116));
    }

    /// The positional join is right: every joined vendor's sale count equals the client's, and Eva's
    /// sale 23 is the Command emblem for 570 Glimmer in the client's own table.
    #[test]
    fn the_rules_join_the_client_sale_table() {
        let t = tables();
        let sales = fixture_sales();
        for v in t.vendors.values() {
            let client = sales.keys().filter(|k| k.0 == v.index).count();
            assert_eq!(client, v.sales as usize, "vendor {} ({})", v.index, v.name);
        }
        assert_eq!(sales[&(6, 23)].item, 840);
        assert_eq!(sales[&(6, 23)].costs, vec![(869, 570, 0x1f)]);
    }
}
